describe('ChatOrchestrator tool input rejection', () => {
  it('resolves after a schema-rejected tool call is retried with corrected input, showing the provider the rejection', async () => {
    const rounds: MessageChunk[][] = [
      [{type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}}, STOP_FOR_TOOL],
      [{type: 'tool_use', toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}}}, STOP_FOR_TOOL],
      [{type: 'text', text: 'sunny in Paris'}, STOP_DONE],
    ];
    const sentToProvider: SendMessageParams['messages'][] = [];
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        sentToProvider.push([...params.messages]);
        for (const chunk of rounds[sentToProvider.length - 1] ?? []) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Weather lookup',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => `sunny in ${String(input.location)}`
    );
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

    const text = await orchestrator.processMessage(createSession('weather?'));

    expect({text, secondRound: JSON.stringify(sentToProvider[1]?.at(-1))}).toEqual({
      text: 'sunny in Paris',
      secondRound: expect.stringMatching(/tool_result.*location.*required/),
    });
  });
});
EOF
